/** Department card illustration (public/art/departments, generated by scripts/design/department-art.mjs) and its alt text,
 * chosen from the department's real name. Names are matched in order, so "Electronics" is tested before "Electrical". */
const ART:[RegExp,string,string][]=[
 [/artificial|machine learning|data science/i,'ai','Neural network layers with connected nodes'],
 [/computer|information tech|software/i,'computer','Code editor window beside a microchip'],
 [/electronic|communication/i,'electronics','Circuit board traces around a central chip'],
 [/electrical|power/i,'electrical','Power transmission tower with a lightning bolt'],
 [/mechanical|automobile|manufactur|production/i,'mechanical','Three interlocking machine gears'],
 [/civil|structur/i,'civil','Suspension bridge over water'],
 [/aero|space/i,'aerospace','Launch vehicle rising along its trajectory'],
 [/chemical engineering/i,'chemical','Process vessels connected by a pipe'],
 [/chemistry|biochem/i,'chemistry','Ring molecule with bonded atoms'],
 [/bio/i,'biotech','DNA double helix and a cell'],
 [/physics/i,'physics','Atom with three electron orbits'],
 [/math|statistic/i,'mathematics','Function curves plotted on axes'],
 [/management|economics|business|finance/i,'management','Rising bar chart with a trend line'],
 [/humanities|social|law|language|english/i,'humanities','Open book with a speech bubble'],
 [/metallurg|material/i,'metallurgy','Crystal lattice of atoms'],
 [/ocean|marine|naval/i,'ocean','Sailboat on ocean waves'],
 [/textile/i,'textile','Interwoven warp and weft threads'],
 [/mining|geolog/i,'mining','Mountain with a mine tunnel and cart'],
 [/architect|planning/i,'architecture','Building facade with arches and a pediment'],
 [/agricultur|food/i,'agriculture','Crop rows, a young plant and a leaf'],
 [/atmospher|climate|energy|environment|sustainab/i,'atmosphere','Sun, cloud and wind lines'],
 [/nano/i,'nano','Hexagonal nanomaterial lattice'],
 [/design/i,'design','Drafting board with set square and compass']
];
export function departmentArt(name:string){
 const hit=ART.find(([re])=>re.test(name));
 return hit?{src:'/art/departments/'+hit[1]+'.svg',alt:hit[2]}:{src:'/art/departments/general.svg',alt:'Globe connected to points around it'};
}
